        }

        /* ==================== PC端响应式优化 ==================== */
        @media (min-width: 768px) {
            body {
                background: #e8e8e8;
            }

            .dark body,
            body.dark {
                background: #121212;
            }

            .header {
                max-width: 800px;
                left: 50%;
                transform: translateX(-50%);
                border-radius: 0 0 12px 12px;
                box-shadow: 0 2px 12px rgba(0,0,0,0.08);
            }

            .main-container {
                max-width: 800px;
                margin: 0 auto;
                padding-top: 72px;
                background: transparent;
            }

            .paragraph-quote {
                margin: 16px 0;
                border-radius: 12px;
                box-shadow: 0 2px 8px rgba(0,0,0,0.04);
            }

            .hot-section {
                margin: 16px 0;
            }

            .comment-list {
                border-radius: 12px;
                box-shadow: 0 2px 8px rgba(0,0,0,0.04);
