    let likeAuthors = getFromCacheMap("likeAuthorsMap")
    if (likeAuthors.size === 0) likeAuthors = getFromCacheMap("likeAuthors")

    let word = String(result.get("文本框")).trim()
    if (word.startsWith("@") || word.startsWith("＠")) {
